import 'package:flutter/material.dart';

class SpacesScreen extends StatelessWidget { const SpacesScreen({super.key}); @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Spaces')), body: ListView(padding: const EdgeInsets.all(20), children: [Text('Choose the kind of room you need.', style: Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight: FontWeight.bold)), const SizedBox(height: 8), const Text('Spaces set the tone. They never define who you are.', style: TextStyle(color: Color(0xFFAAA8B8))), const SizedBox(height: 26), const _Space(icon: Icons.hearing, title: 'Just Listen', text: 'A quiet place to be heard without needing advice.', count: '1.2k here now'), const SizedBox(height: 14), const _Space(icon: Icons.forum_outlined, title: 'Open Discussion', text: 'Share perspectives with people who want to engage thoughtfully.', count: '846 here now'), const SizedBox(height: 30), const _Empty(label: 'More Spaces are taking shape', icon: Icons.auto_awesome)])); }
class _Space extends StatelessWidget { final IconData icon; final String title, text, count; const _Space({required this.icon, required this.title, required this.text, required this.count}); @override Widget build(BuildContext context) => Card(child: InkWell(borderRadius: BorderRadius.circular(14), onTap: () {}, child: Padding(padding: const EdgeInsets.all(20), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Icon(icon, color: Theme.of(context).colorScheme.secondary), const SizedBox(height: 18), Text(title, style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.bold)), const SizedBox(height: 8), Text(text, style: const TextStyle(color: Color(0xFFAAA8B8))), const SizedBox(height: 18), Text(count, style: TextStyle(color: Theme.of(context).colorScheme.primary, fontSize: 12))])))); }
class _Empty extends StatelessWidget { final String label; final IconData icon; const _Empty({required this.label, required this.icon}); @override Widget build(BuildContext context) => Center(child: Column(children: [Icon(icon, color: const Color(0xFFAAA8B8)), const SizedBox(height: 8), Text(label, style: const TextStyle(color: Color(0xFFAAA8B8)))])); }
